import csv
import math
import sys
from collections import defaultdict


def mean(xs):
    return sum(xs) / len(xs) if xs else float("nan")


def prob_diff(records, exposure_index, outcome_index):
    exposed = [r[outcome_index] for r in records if r[exposure_index] == 1]
    unexposed = [r[outcome_index] for r in records if r[exposure_index] == 0]
    return len(exposed), mean(exposed), len(unexposed), mean(unexposed), mean(exposed) - mean(unexposed)


